<script setup lang="ts">import { computed,ref } from 'vue';import { useAppStore } from '@/stores/app';import { checklistProgress,isOverdue } from '@/domain/tasks';import UiIcon from '@/components/UiIcon.vue';const store=useAppStore();const query=ref('');const adding=ref<string|null>(null);const title=ref('');const boardName=ref('');const cards=(columnId:string)=>store.activeBoard?.columns.find(c=>c.id===columnId)?.cards.filter(c=>!c.archived&&(!query.value||[c.title,c.description,...c.labels].join(' ').toLowerCase().includes(query.value.toLowerCase())))??[];const count=computed(()=>store.activeBoard?.columns.flatMap(c=>c.cards).length??0);const add=(columnId:string)=>{if(title.value.trim())store.addCard(columnId,title.value.trim());title.value='';adding.value=null};const createBoard=()=>{if(boardName.value.trim())store.addBoard(boardName.value.trim());boardName.value=''}</script>
<template><section><div class="page-heading compact"><div><p class="kicker">ORGANIZACJA PRACY</p><h1>Zadania</h1><p>{{count}} kart w aktywnej tablicy.</p></div><form class="inline-form" @submit.prevent="createBoard"><input v-model="boardName" aria-label="Nazwa nowej tablicy" placeholder="Nowa tablica"><button class="button secondary" type="submit"><UiIcon name="Plus"/> Tablica</button></form></div><div class="task-toolbar"><div class="board-tabs" role="tablist" aria-label="Tablice"><button v-for="board in store.data.tasks.boards.filter(b=>!b.archived)" :key="board.id" role="tab" :aria-selected="board.id===store.data.tasks.activeBoardId" :class="{active:board.id===store.data.tasks.activeBoardId}" @click="store.data.tasks.activeBoardId=board.id;store.persist()">{{board.name}}</button></div><label class="search"><UiIcon name="Search" :size="17"/><span class="sr-only">Szukaj kart</span><input v-model="query" placeholder="Szukaj kart"></label></div><div class="kanban" aria-label="Tablica kanban"><section v-for="column in store.activeBoard?.columns" :key="column.id" class="kanban-column" @dragover.prevent @drop="store.moveCard(String($event.dataTransfer?.getData('text/plain')),column.id)"><header><h2>{{column.name}}</h2><span>{{cards(column.id).length}}</span></header><div class="cards"><article v-for="card in cards(column.id)" :key="card.id" class="task-card" draggable="true" tabindex="0" @dragstart="$event.dataTransfer?.setData('text/plain',card.id)"><div class="labels"><i v-for="label in card.labels" :key="label">{{label}}</i></div><div class="task-title"><b>{{card.title}}</b><button class="icon-button danger" :aria-label="`Usuń ${card.title}`" @click="store.deleteCard(card.id)"><UiIcon name="X" :size="15"/></button></div><p v-if="card.description">{{card.description}}</p><div v-if="card.checklist.length" class="check"><progress :value="checklistProgress(card)" max="100"/><span>{{checklistProgress(card)}}%</span></div><footer><span v-if="card.dueDate" :class="{overdue:isOverdue(card)}"><UiIcon name="Calendar" :size="14"/>{{new Date(card.dueDate).toLocaleDateString('pl-PL',{day:'numeric',month:'short'})}}</span><span><UiIcon name="ListChecks" :size="14"/>{{card.checklist.length}}</span></footer></article></div><form v-if="adding===column.id" class="quick-add" @submit.prevent="add(column.id)"><label><span class="sr-only">Tytuł karty</span><textarea v-model="title" autofocus required placeholder="Tytuł zadania"/></label><div><button class="button primary" type="submit">Dodaj</button><button class="icon-button" type="button" aria-label="Anuluj" @click="adding=null"><UiIcon name="X"/></button></div></form><button v-else class="add-card" @click="adding=column.id"><UiIcon name="Plus" :size="17"/> Dodaj kartę</button></section></div></section></template>
